const p = $json.body || $json;
const pedido = p.pedido || p.order || p;
const bruto = String(p.evento || p.event || pedido.status || '').toLowerCase();
const aliases = {order_on_the_way:'saiu_entrega',delivery_assigned:'saiu_entrega',order_delivered:'concluido'};
const evento = aliases[bruto] || bruto.replace(/^order_status_/, '');
const codigo = pedido.codigo || pedido.id || p.order_id || '';
const nome = pedido.cliente_nome || pedido.nome || 'cliente';
const telefone = String(pedido.cliente_whatsapp || pedido.whatsapp || pedido.telefone || '').replace(/\D/g, '');
const mensagens = {
  novo: `Olá, ${nome}! Recebemos o pedido #${codigo}.`,
  aceito: `Pedido #${codigo} aceito e enviado para a cozinha.`,
  em_preparo: `Seu pedido #${codigo} está em preparo. 👨‍🍳`,
  preparando: `Seu pedido #${codigo} está em preparo. 👨‍🍳`,
  pronto: `Seu pedido #${codigo} ficou pronto! ✅`,
  despachado: `Seu pedido #${codigo} saiu para entrega. 🛵`,
  saiu_entrega: `Seu pedido #${codigo} saiu para entrega. 🛵`,
  concluido: `Pedido #${codigo} concluído. Obrigado pela preferência!`,
  entregue: `Pedido #${codigo} concluído. Obrigado pela preferência!`,
  cancelado: `O pedido #${codigo} foi cancelado. Se precisar, fale com nossa equipe.`
};
const mensagem = mensagens[evento] || `O pedido #${codigo} foi atualizado: ${evento.replaceAll('_',' ')}.`;
return [{json:{telefone,mensagem,evento,codigo}}];
